using StardewModdingAPI;\nusing StardewValley.Menus;\n\nnamespace EnhancedSchoolsMod\n{\n    public class CalendarHandler\n    {\n        private readonly IModHelper Helper;\n        private readonly DataManager DataManager;\n        private readonly SchoolManager SchoolManager;\n        private readonly IMonitor Monitor;\n\n        public CalendarHandler(IModHelper helper, DataManager dataManager, SchoolManager schoolManager, IMonitor monitor)\n        {\n            Helper = helper;\n            DataManager = dataManager;\n            SchoolManager = schoolManager;\n            Monitor = monitor;\n        }\n\n        public void HandleMenuChanged(IClickableMenu? newMenu) => Monitor.Log(\"Calendar integration ready.\", LogLevel.Trace);\n        public void ShowSchoolEnrollmentMenu() => Monitor.Log(\"School enrollment menu ready.\", LogLevel.Info);\n    }\n}